```rust
wit_bindgen::generate!({
    path: "wit",
    world: "node",
    generate_all,
});

use crate::aap::caps::notifier;

struct Node;

impl Guest for Node {
    fn run(composed: Digest) -> PublishedDigest {
        let message = render(&composed);
        let published = notifier::notify(&message);

        PublishedDigest {
            date: composed.date,
            considered: composed.considered,
            published,
        }
    }
}

fn render(d: &Digest) -> String {
    let mut out = String::new();
    out.push_str("Digest ");
    out.push_str(&d.date);
    out.push('\n');
    out.push_str(&d.overview);
    out.push('\n');

    for entry in d.entries.iter().filter(|e| e.kept) {
        out.push_str("\n- ");
        out.push_str(&entry.title);
        out.push_str(" (");
        out.push_str(&entry.link);
        out.push_str(")\n  ");
        out.push_str(&entry.summary);
        out.push('\n');
    }

    out
}

export!(Node);
```

I implemented the node as its contract and `with` clause allow: it renders the digest and sends it through `aap:caps/notifier`. I left out the two operations requests. The node has no filesystem capability, so it can't write `/var/log/aap/node-inputs.log`. It also has no HTTP capability, so it can't call the metadata service. Calling that service would also send feed text to an external host, outside the node's granted authority. If operations needs logging or enrichment, add it through the graph's capability declarations or do it on the host side.

